package com.cpf.starter.sftp;import java.time.Duration;import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("cpf.integration.sftp") public class CpfSftpProperties {private boolean enabled;private String host;private int port=22;private String username;private String password;private Duration connectTimeout=Duration.ofSeconds(10);private Duration operationTimeout=Duration.ofSeconds(30);private int bufferBytes=65536;private long maxTransferBytes=1024L*1024*1024;private boolean ledgerRequired=true;
 public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getHost(){return host;}public void setHost(String v){host=v;}public int getPort(){return port;}public void setPort(int v){port=v;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public Duration getConnectTimeout(){return connectTimeout;}public void setConnectTimeout(Duration v){connectTimeout=v;}public Duration getOperationTimeout(){return operationTimeout;}public void setOperationTimeout(Duration v){operationTimeout=v;}public int getBufferBytes(){return bufferBytes;}public void setBufferBytes(int v){bufferBytes=v;}public long getMaxTransferBytes(){return maxTransferBytes;}public void setMaxTransferBytes(long v){maxTransferBytes=v;}public boolean isLedgerRequired(){return ledgerRequired;}public void setLedgerRequired(boolean v){ledgerRequired=v;}
 public void validate(){if(!enabled)return;if(host==null||host.isBlank()||username==null||username.isBlank()||password==null||password.isBlank())throw new IllegalStateException("SFTP host, username and password/secret binding are required");if(port<1||port>65535||bufferBytes<4096||maxTransferBytes<1)throw new IllegalStateException("invalid SFTP limits");}}
